cd /workspace/probes && cat > run.js <<'EOF'
const {execFile}=require('child_process');
const fs=require('fs');
const EXE='/workspace/dataset/test13_executable';
const OUT='/workspace/probes/error-counting-deep.jsonl';
function runAsync(a,b){return new Promise(res=>{
  execFile(EXE,['--a',a,'--b',b],{encoding:'utf8',maxBuffer:1e8},(err,stdout)=>{
    if(err) res({a,b,out:stdout||'',exit:(err.code===undefined||err.code===null)?-1:err.code});
    else res({a,b,out:stdout,exit:0});
  });});}
async function pool(vectors,conc){
  const results=new Array(vectors.length); let i=0;
  const workers=Array.from({length:conc},async()=>{
    while(true){const k=i++; if(k>=vectors.length)break;
      results[k]=await runAsync(vectors[k][0],vectors[k][1]);}});
  await Promise.all(workers); return results;
}
async function main(vectors,append,conc){
  const r=await pool(vectors,conc||12);
  const lines=r.map(x=>JSON.stringify(x));
  if(append) fs.appendFileSync(OUT,lines.join('\n')+'\n');
  return {r,lines};
}
module.exports={runAsync,pool,main,OUT};
EOF
